// pixels はファミコンの色番号 (enemy_sprite.rs / field_sprite.rs の NES_PALETTE の添字)。
// 座標は EnemySprite と同じ画面座標で、敵はこの上に重ねて表示される。

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BattleBackground {
    pub x: u8,
    pub y: u8,
    pub width: u8,
    pub height: u8,
    pub tiles: &'static [u8], // 14x14 タイル、行優先 (BATTLE_BACKGROUND_TILE_PATTERNS のキー)
    pub palette: [[u8; 3]; 4],
    pub block_palettes: &'static [u8], // 2x2 タイルごとのパレット番号 (7x7、行優先)
    pub reveal_order: &'static [(u8, u8)], // 2x2 ブロックを表示する順 (x, y)。中央から渦巻き状
    pub pixels: &'static [u8],         // 行優先 (index = y * width + x)
}

// 背景のない戦闘 (フィールド以外) はこの色で塗りつぶす
pub const BATTLE_BACKDROP: u8 = 14;

pub fn battle_background(map_id: u8) -> Option<&'static BattleBackground> {
    (map_id == 1).then_some(&BATTLE_BACKGROUND)
}

